1	import type { Claim, Entry, EvidenceRef, Session } from '@dailies/core';
2	import type { CommandClass } from './commands';
3	import { classifyCommand } from './commands';
4	import { collectRuns, parseOutcome, type ToolRun } from './results';
5	import { normalize, quoteMatches } from './quote';
6	
7	type Verdicted = Pick<Claim, 'verdict' | 'reason' | 'evidence'>;
8	
9	const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit']);
10	
11	// Staleness means code changed under the claim, not that some file did: a rewritten evidence note
12	// or data file does not make a test result stale.
13	const SOURCE_EXTENSIONS = new Set([
14	  '.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs', '.py', '.go', '.rs', '.java', '.kt', '.rb', '.php',
15	  '.c', '.cc', '.cpp', '.h', '.hpp', '.cs', '.swift', '.scala', '.sql', '.sh', '.vue', '.svelte',
16	]);
17	const NON_SOURCE_DIRS = new Set(['docs', 'evidence', 'screenshots']);
18	
19	function isSourceEdit(filePath: string): boolean {
20	  const segments = filePath.split('/');
21	  const base = segments[segments.length - 1] ?? '';
22	  const dot = base.lastIndexOf('.');
23	  if (dot <= 0) return false;
24	  if (!SOURCE_EXTENSIONS.has(base.slice(dot).toLowerCase())) return false;
25	  return !segments.slice(0, -1).some((dir) => NON_SOURCE_DIRS.has(dir));
26	}
27	
28	function findEntry(session: Session, entryId: string): Entry | undefined {
29	  return session.entries.find((e) => e.id === entryId);
30	}
31	
32	function entryRef(entryId: string): EvidenceRef {
33	  return { type: 'entry', entryId };
34	}
35	
36	function runEvidence(run: ToolRun): EvidenceRef[] {
37	  const refs: EvidenceRef[] = [entryRef(run.callEntryId)];
38	  if (run.resultEntryId) refs.push(entryRef(run.resultEntryId));
39	  return refs;
40	}
41	
42	function unverifiable(reason: string): Verdicted {
43	  return { verdict: 'unverifiable', reason, evidence: [] };
44	}
45	
46	// Shared by tests_pass (class ['test']) and build_passes (classes ['build', 'typecheck', 'lint']):
47	// consider the last matching run before the claim's entry, then check for an edit since.
48	function lastRunVerdict(claim: Claim, session: Session, classes: CommandClass[], noRunReason: string): Verdicted {
49	  const claimEntry = findEntry(session, claim.entryId);
50	  if (!claimEntry) return unverifiable('claim entry not found in session');
51	
52	  const runs = collectRuns(session).filter((r) => classes.includes(r.cls) && r.index < claimEntry.index);
53	  if (runs.length === 0) return unverifiable(noRunReason);
54	
55	  const last = runs[runs.length - 1]!;
56	  if (last.outcome === 'fail') return { verdict: 'contradicted', reason: 'the last recorded run failed', evidence: runEvidence(last) };
57	  if (last.outcome === 'unknown') {
58	    // Only a test run has this distinction: an errored shell call with no recognised test summary never ran
59	    // the tests, so saying "the last run failed" would be false. Other classes already fail on isError alone.
60	    const resultEntry = last.cls === 'test' && last.resultEntryId ? findEntry(session, last.resultEntryId) : undefined;
61	    if (resultEntry?.isError) return unverifiable('the last test command exited with an error before reporting results');
62	    return unverifiable('the last recorded run output was not recognised');
63	  }
64	
65	  const edit = session.entries.find(
66	    (e) =>
67	      e.kind === 'tool_call' &&
68	      e.index > last.index &&
69	      e.index < claimEntry.index &&
70	      e.toolName !== undefined &&
71	      EDIT_TOOLS.has(e.toolName) &&
72	      e.filePath !== undefined &&
73	      isSourceEdit(e.filePath)
74	  );
75	  if (edit) {
76	    return {
77	      verdict: 'stale',
78	      reason: 'a source file was edited after the last passing run',
79	      evidence: [entryRef(edit.id), ...runEvidence(last)],
80	    };
81	  }
82	  return { verdict: 'verified', reason: 'the last recorded run passed with no edits after', evidence: runEvidence(last) };
83	}
84	
85	function ranCommand(claim: Claim, session: Session): Verdicted {
86	  const claimEntry = findEntry(session, claim.entryId);
87	  if (!claimEntry || !claim.subject) return unverifiable('no matching command is recorded before this message');
88	
89	  const subject = normalize(claim.subject);
90	  if (!subject) return unverifiable('no matching command is recorded before this message');
91	  const calls = session.entries.filter(
92	    (e) => e.kind === 'tool_call' && e.index < claimEntry.index && e.command && normalize(e.command).includes(subject)
93	  );
94	  if (calls.length === 0) return unverifiable('no matching command is recorded before this message');
95	
96	  const call = calls[calls.length - 1]!;
97	  const result = session.entries.find((e) => e.kind === 'tool_result' && e.toolUseId === call.toolUseId);
98	  if (!result) return unverifiable('the matching command has no recorded result');
99	
100	  const evidence = [entryRef(call.id), entryRef(result.id)];
101	  if (result.isError) return { verdict: 'contradicted', reason: 'the matching command errored', evidence };
102	  return { verdict: 'verified', reason: 'the matching command succeeded', evidence };
103	}
104	
105	function fixedError(claim: Claim, session: Session): Verdicted {
106	  const claimEntry = findEntry(session, claim.entryId);
107	  if (!claimEntry || !claim.subject) return unverifiable('no error text is recorded for this claim');
108	
109	  const subject = normalize(claim.subject);
110	  if (!subject) return unverifiable('no error text is recorded for this claim');
111	  const errorResult = session.entries.find(
112	    (e) => e.kind === 'tool_result' && e.index < claimEntry.index && normalize(e.text).includes(subject)
113	  );
114	  if (!errorResult) return unverifiable('the error text is not recorded in any tool result');
115	
116	  const errorCall = session.entries.find((e) => e.kind === 'tool_call' && e.toolUseId === errorResult.toolUseId);
117	  if (!errorCall || !errorCall.command) return unverifiable('the failing command is not recorded');
118	  const cls = classifyCommand(errorCall.command);
119	
120	  const laterCalls = session.entries.filter(
121	    (e) =>
122	      e.kind === 'tool_call' &&
123	      e.index > errorResult.index &&
124	      e.index < claimEntry.index &&
125	      e.command &&
126	      classifyCommand(e.command) === cls
127	  );
128	  if (laterCalls.length === 0) return unverifiable('no later run of the same kind is recorded before this message');
129	
130	  const lastCall = laterCalls[laterCalls.length - 1]!;
131	  const lastResult = session.entries.find((e) => e.kind === 'tool_result' && e.toolUseId === lastCall.toolUseId);
132	  if (!lastResult) return unverifiable('the later run has no recorded result');
133	
134	  const outcome = parseOutcome(cls, lastResult.text, lastResult.isError ?? false);
135	  const stillPresent = normalize(lastResult.text).includes(subject);
136	  const evidence: EvidenceRef[] = [entryRef(errorResult.id), entryRef(lastCall.id), entryRef(lastResult.id)];
137	
138	  if (stillPresent || outcome === 'fail') {
139	    return { verdict: 'contradicted', reason: 'the error is still present in a later run', evidence };
140	  }
141	  if (outcome === 'unknown') return unverifiable('the later run output was not recognised');
142	  return { verdict: 'verified', reason: 'a later run no longer shows the error', evidence };
143	}
144	
145	export function verifyClaim(claim: Claim, session: Session): Claim {
146	  if (claim.kind === 'implemented') return claim;
147	
148	  const entry = findEntry(session, claim.entryId);
149	  if (!entry || !quoteMatches(claim.quote, entry.text)) {
150	    return { ...claim, verdict: 'unverifiable', reason: 'quote not found in transcript', evidence: [] };
151	  }
152	
153	  let result: Verdicted;
154	  switch (claim.kind) {
155	    case 'tests_pass':
156	      result = lastRunVerdict(claim, session, ['test'], 'no test run is recorded before this message');
157	      break;
158	    case 'build_passes':
159	      result = lastRunVerdict(claim, session, ['build', 'typecheck', 'lint'], 'no build, typecheck or lint run is recorded before this message');
160	      break;
161	    case 'ran_command':
162	      result = ranCommand(claim, session);
163	      break;
164	    case 'fixed_error':
165	      result = fixedError(claim, session);
166	      break;
167	    default:
168	      result = unverifiable('unknown claim kind');
169	  }
170	  return { ...claim, ...result };
171	}
172	
173	export function verifyClaims(claims: Claim[], sessions: Session[]): Claim[] {
174	  const byId = new Map(sessions.map((s) => [s.id, s]));
175	  return claims.map((c) => {
176	    const session = byId.get(c.sessionId);
177	    if (!session) return { ...c, verdict: 'unverifiable', reason: 'session not found', evidence: [] };
178	    return verifyClaim(c, session);
179	  });
180	}
