1	import type { Claim, Entry, Session } from '@dailies/core';
2	
3	export type PartialEntry = {
4	  kind: Entry['kind'];
5	  text?: string;
6	  ts?: string | null;
7	  toolName?: string;
8	  toolUseId?: string;
9	  command?: string;
10	  filePath?: string;
11	  isError?: boolean;
12	};
13	
14	export function session(entries: PartialEntry[], opts: { id?: string } = {}): Session {
15	  const id = opts.id ?? 's1';
16	  const fullEntries: Entry[] = entries.map((e, index) => ({
17	    id: `${id}:${index}`,
18	    sessionId: id,
19	    index,
20	    ts: e.ts ?? null,
21	    kind: e.kind,
22	    text: e.text ?? '',
23	    toolName: e.toolName,
24	    toolUseId: e.toolUseId,
25	    command: e.command,
26	    filePath: e.filePath,
27	    isError: e.isError,
28	  }));
29	  return {
30	    id,
31	    checkpointIds: ['cp1'],
32	    agent: 'claude-code',
33	    model: 'claude-sonnet-4.6',
34	    branch: 'main',
35	    startedAt: '2026-10-10T07:00:00Z',
36	    endedAt: '2026-10-10T07:30:00Z',
37	    turnCount: fullEntries.length,
38	    tokens: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
39	    commits: [],
40	    filesTouched: [],
41	    entries: fullEntries,
42	  };
43	}
44	
45	export function claim(partial: {
46	  id?: string;
47	  sessionId: string;
48	  entryId: string;
49	  quote: string;
50	  kind: Claim['kind'];
51	  subject?: string;
52	}): Claim {
53	  return {
54	    id: partial.id ?? 'c1',
55	    sessionId: partial.sessionId,
56	    entryId: partial.entryId,
57	    quote: partial.quote,
58	    kind: partial.kind,
59	    subject: partial.subject,
60	    evidence: [],
61	  };
62	}
