1	import { describe, expect, it } from 'vitest';
2	import { collectRuns, headlineFor, parseOutcome } from '../src/index';
3	import { session } from './helpers';
4	
5	describe('parseOutcome', () => {
6	  it('parses outcomes and strips colour codes', () => {
7	    expect(parseOutcome('test', '\u001b[31m Tests  2 failed\u001b[0m | 14 passed', false)).toBe('fail');
8	    expect(parseOutcome('test', ' Test Files  3 passed (3)\n Tests  14 passed (14)', false)).toBe('pass');
9	    expect(parseOutcome('test', 'ok  \tgithub.com/x/y\t0.21s', false)).toBe('pass');
10	    expect(parseOutcome('test', 'some unrelated text', false)).toBe('unknown');
11	    expect(parseOutcome('typecheck', 'src/a.ts(3,1): error TS2322: nope', false)).toBe('fail');
12	  });
13	
14	  it('treats isError as fail for a non-test class regardless of the output text', () => {
15	    expect(parseOutcome('build', 'built in 1.2s', true)).toBe('fail');
16	  });
17	
18	  it('does not fail a test run merely because its command errored: a recognised failing summary is required', () => {
19	    expect(parseOutcome('test', 'No module named pytest', true)).toBe('unknown');
20	  });
21	
22	  it('still fails an errored test run when the output has a recognised failing summary', () => {
23	    expect(parseOutcome('test', '2 failed, 8 passed', true)).toBe('fail');
24	  });
25	
26	  it('does not treat a zero count as a failure marker', () => {
27	    expect(parseOutcome('test', '0 failed, 14 passed', false)).toBe('pass');
28	  });
29	
30	  it('still detects a failure count that appears after an earlier zero count', () => {
31	    expect(parseOutcome('test', '0 failed, 14 passed\nSuite 2: 3 failing', false)).toBe('fail');
32	  });
33	
34	  it('recognises typecheck pass and fail markers', () => {
35	    expect(parseOutcome('typecheck', 'Found 0 errors', false)).toBe('pass');
36	    expect(parseOutcome('typecheck', '', false)).toBe('pass');
37	    expect(parseOutcome('typecheck', 'Found 3 errors', false)).toBe('fail');
38	  });
39	
40	  it('recognises build and lint pass/fail/unknown markers', () => {
41	    expect(parseOutcome('build', 'compiled successfully', false)).toBe('pass');
42	    expect(parseOutcome('build', '3 errors', false)).toBe('fail');
43	    expect(parseOutcome('lint', 'something unexpected', false)).toBe('unknown');
44	    expect(parseOutcome('lint', '0 problems', false)).toBe('pass');
45	  });
46	
47	  it('trusts a clean exit for typecheck when the output has no recognised marker', () => {
48	    expect(parseOutcome('typecheck', '$ tsc --noEmit', false, { exitTrusted: true })).toBe('pass');
49	  });
50	
51	  it('does not trust the exit status when exitTrusted is false, even with the same clean output', () => {
52	    expect(parseOutcome('typecheck', '$ tsc --noEmit', false, { exitTrusted: false })).toBe('unknown');
53	    expect(parseOutcome('typecheck', '$ tsc --noEmit', false)).toBe('unknown');
54	  });
55	
56	  it('still fails on a recognised error marker whatever the exit status', () => {
57	    expect(parseOutcome('typecheck', 'error TS2322: nope', false, { exitTrusted: true })).toBe('fail');
58	    expect(parseOutcome('typecheck', 'error TS2322: nope', false, { exitTrusted: false })).toBe('fail');
59	  });
60	
61	  it('trusts a clean exit for lint and build too', () => {
62	    expect(parseOutcome('lint', 'no output the parser recognises', false, { exitTrusted: true })).toBe('pass');
63	    expect(parseOutcome('build', 'no output the parser recognises', false, { exitTrusted: true })).toBe('pass');
64	  });
