15	function models(o: { rejects?: (text: string) => boolean; rewrites?: unknown[] } = {}): (req: MockRequest) => ChatMessage {
16	  const rewrites = [...(o.rewrites ?? [])];
17	  return (req) => {
18	    if (req.role === 'judge') return json({ entailed: !(o.rejects?.(userText(req)) ?? false) });
19	    if (req.role === 'writer') {
20	      if (rewrites.length === 0) throw new Error('no rewrite was expected here');
21	      return json(rewrites.shift());
22	    }
23	    throw new Error(`unexpected role ${req.role}`);
24	  };
25	}
