10	/** The entry ids a request hands the extractor: each message is given as JSON `{ entryId, text }`. */
11	const givenEntryIds = (req: MockRequest) => [...userText(req).matchAll(/"entryId":\s*"([^"]+)"/g)].map((m) => m[1]!);
12	
13	/** An extractor that answers per session, and a judge with one fixed answer. */
14	function scripted(claims: Record<string, unknown[]>, judge?: unknown): (req: MockRequest) => ChatMessage {
15	  return (req) => {
16	    if (req.role === 'judge') {
17	      if (judge === undefined) throw new Error('the judge was not expected to be asked');
18	      return json(judge);
19	    }
20	    const sessionId = givenEntryIds(req)[0]!.split(':')[0]!;
21	    return json({ claims: claims[sessionId] ?? [] });
22	  };
23	}
